import ApiService from '../services/api';

export const downloadCarbonFootprintCsvFromApi = async () => {
  const blob = await ApiService.downloadCarbonFootprintCsv();
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = 'carbon-footprint-export.csv';
  link.click();
  URL.revokeObjectURL(url);
};
